        struct _bosdyn_api_spot_KneelCircleParams *kneel_circle_params;
        struct _bosdyn_api_spot_GripperParams *gripper_params;
        struct _bosdyn_api_spot_HopParams *hop_params;
        struct _bosdyn_api_spot_RandomRotateParams *random_rotate_params;
        struct _bosdyn_api_spot_CrawlParams *crawl_params;
        struct _bosdyn_api_spot_SideParams *side_params;
        struct _bosdyn_api_spot_BourreeParams *bourree_params;
        struct _bosdyn_api_spot_WorkspaceArmMoveParams *workspace_arm_move_params;
