    struct _google_protobuf_DoubleValue *elbow_0;
    struct _google_protobuf_DoubleValue *elbow_1;
    struct _google_protobuf_DoubleValue *wrist_0;
    struct _google_protobuf_DoubleValue *wrist_1;
